if (!Number.isInteger(n) || n < 0 || n > 1_000_000) throw new Error("Invalid n");
let a = 0n;
let b = 1n;
let k = n;
let bit = 1;
while (bit <= k / 2) bit *= 2;
while (bit > 0) {
  const c = a * (2n * b - a);
  const d = a * a + b * b;
  if (Math.floor(k / bit) % 2 === 0) {
    a = c;
    b = d;
  } else {
    a = d;
    b = c + d;
  }
  k %= bit;
  bit = Math.floor(bit / 2);
}
return a;

